import { NextResponse } from 'next/server'
import type { NextRequest } from 'next/server'

// No `config.matcher` is exported, so this runs on every request
// (pages, route handlers, _next/static, _next/image, public assets, etc.).
export function proxy(request: NextRequest) {
  console.log(
    `[${new Date().toISOString()}] ${request.method} ${request.nextUrl.pathname}${request.nextUrl.search}`
  )
  return NextResponse.next()
}

